export type SearchCatalogData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * The query; never logged.
         */
        q?: string;
        /**
         * Only these providers.
         */
        provider?: Array<string> | null;
        /**
         * Only these sources of a provider with sources.
         */
        source?: Array<string> | null;
        /**
         * Only these item kinds.
         */
        kind?: Array<string> | null;
        /**
         * popular: the most viewed first, where a source can; one that cannot names sort in unenforced.
         */
        sort?: 'relevance' | 'popular';
        /**
         * Only items uploaded this recently, where a source can.
         */
        uploaded?: 'today' | 'week' | 'month' | 'year';
        /**
         * short is under 3 min, medium 3 to 20, long over 20, where a source can.
         */
        duration?: 'short' | 'medium' | 'long';
        /**
         * An event's next, with provider and source naming it.
         */
        cursor?: string;
        limit?: number;
    };
    url: '/catalog/search';
};

